    def _load_or_create_admin_token(self, *, allow_create: bool = True) -> str:
        env_token = str(os.getenv("CLOUDS_CODER_ADMIN_TOKEN", "") or "").strip()
        if env_token:
            return env_token
        try:
            if self.admin_token_path.exists():
                token = self.admin_token_path.read_text(encoding="utf-8").strip()
                if len(token) >= 24:
                    return token
        except Exception:
            pass
        if not allow_create:
            return ""
        token = "cc_admin_" + base64.urlsafe_b64encode(os.urandom(32)).decode("ascii").rstrip("=")
        try:
            fd = os.open(self.admin_token_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            with os.fdopen(fd, "w", encoding="utf-8") as handle:
                handle.write(token + "\n")
                handle.flush()
                try:
                    os.fsync(handle.fileno())
                except Exception:
                    pass
        except FileExistsError:
            try:
                existing = self.admin_token_path.read_text(encoding="utf-8").strip()
                if len(existing) >= 24:
                    return existing
            except Exception:
                pass
            raise RuntimeError("admin token file already exists but is invalid")
        return token

    def verify_admin_token(self, token: str) -> str:
        candidate = str(token or "").strip()
        if not candidate:
            return ""
        expected = str(getattr(self, "admin_token", "") or "")
        if expected and hmac.compare_digest(candidate, expected):
            return "token"
        try:
            if self.admin_auth.verify_session(candidate):
                return "session"
        except Exception:
            pass
        return ""

    def admin_auth_status(self, *, local_setup_allowed: bool) -> dict:
        configured = bool(self.admin_auth.configured())
        return {
            "setup_required": not configured,
            "password_login_enabled": configured,
            "token_login_enabled": bool(str(self.admin_token or "").strip()),
            "local_setup_allowed": bool((not configured) and local_setup_allowed),
            "setup_local_only": True,
            "session_ttl_seconds": ADMIN_AUTH_SESSION_TTL_SECONDS,
        }

    def setup_admin(
        self,
        username: object,
        password: object,
        *,
        local_setup_allowed: bool,
        bootstrap_token: str = "",
    ) -> dict:
        if self.admin_auth.configured():
            raise AdminAuthError("setup_already_completed", "管理员已经创建，请直接登录", 409)
        bootstrap_ok = self.verify_admin_token(bootstrap_token) == "token"
        if not local_setup_allowed and not bootstrap_ok:
            raise AdminAuthError(
                "setup_local_only",
                "首次创建管理员仅允许在本机进行；远程初始化需提供现有 Admin Token",
                403,
            )
        return self.admin_auth.setup(username, password)

    def login_admin(self, username: object, password: object, client_ip: str) -> dict:
        if not self.admin_auth.configured():
            raise AdminAuthError("setup_required", "请先创建管理员账号", 409)
        return self.admin_auth.login(username, password, client_ip)

    def exchange_admin_token(self, token: str) -> dict:
        if self.verify_admin_token(token) != "token":
            raise AdminAuthError("invalid_token", "Admin Token 无效", 401)
        return self.admin_auth.issue_session(username_key="__token__", auth_version=0)

    def logout_admin(self, token: str) -> None:
        self.admin_auth.revoke_session(token)

    def configure_admin_runtime(self, active_config: dict, initial_config: dict | None = None) -> None:
        clean, errors = _admin_coerce_config(active_config)
        if not errors:
            clean.pop("_effective_ports", None)
            self.admin_active_config = clean
        if isinstance(initial_config, dict):
            initial, initial_errors = _admin_coerce_config(initial_config)
            if not initial_errors:
                initial.pop("_effective_ports", None)
                self.admin_initial_config = initial

    def admin_config_payload(self) -> dict:
        with self.admin_config_lock:
            stored = _read_json_file(self.admin_config_path, {})
            draft_raw = stored.get("draft", self.admin_active_config) if isinstance(stored, dict) else self.admin_active_config
            defaults_raw = stored.get("defaults", self.admin_initial_config) if isinstance(stored, dict) else self.admin_initial_config
            draft, draft_errors = _admin_coerce_config(draft_raw)
            defaults, default_errors = _admin_coerce_config(defaults_raw)
            ports = dict(draft.pop("_effective_ports", {}) or {})
            defaults.pop("_effective_ports", None)
            revision_material = json.dumps(
                {"draft": draft, "defaults": defaults, "updated_at": float(stored.get("updated_at", 0.0) or 0.0) if isinstance(stored, dict) else 0.0},
                ensure_ascii=False, sort_keys=True, separators=(",", ":"),
            )
            return {
                "boot_id": str(getattr(self.telemetry, "boot_id", "") or ""),
                "revision": hashlib.sha256(revision_material.encode("utf-8")).hexdigest()[:24],
                "schema": _admin_config_schema(), "active": dict(self.admin_active_config), "draft": draft,
                "defaults": defaults, "initial": dict(self.admin_initial_config), "effective_ports": ports,
                "validation_errors": draft_errors + default_errors, "restart_required": draft != self.admin_active_config,
                "restart_error": _read_json_file(self.admin_restart_error_path, {}),
                "updated_at": float(stored.get("updated_at", 0.0) or 0.0) if isinstance(stored, dict) else 0.0,
            }

    def save_admin_config(self, values: object, *, set_default: bool = False, expected_revision: str = "") -> dict:
        clean, errors = _admin_coerce_config(values)
        ports = dict(clean.pop("_effective_ports", {}) or {})
        if errors:
            return {"ok": False, "errors": errors, "config": clean, "effective_ports": ports}
        with self.admin_config_lock:
            current = _read_json_file(self.admin_config_path, {})
            current_draft, _ = _admin_coerce_config(current.get("draft", self.admin_active_config) if isinstance(current, dict) else self.admin_active_config)
            current_defaults, _ = _admin_coerce_config(current.get("defaults", self.admin_initial_config) if isinstance(current, dict) else self.admin_initial_config)
            current_draft.pop("_effective_ports", None)
            current_defaults.pop("_effective_ports", None)
            current_material = json.dumps(
                {"draft": current_draft, "defaults": current_defaults, "updated_at": float(current.get("updated_at", 0.0) or 0.0) if isinstance(current, dict) else 0.0},
                ensure_ascii=False, sort_keys=True, separators=(",", ":"),
            )
            current_revision = hashlib.sha256(current_material.encode("utf-8")).hexdigest()[:24]
            if expected_revision and not hmac.compare_digest(str(expected_revision), current_revision):
                return {"ok": False, "conflict": True, "error": "startup config changed; reload before saving", "revision": current_revision}
            defaults = current.get("defaults", self.admin_initial_config) if isinstance(current, dict) else self.admin_initial_config
            payload = {"version": 1, "draft": clean, "defaults": clean if set_default else defaults, "updated_at": now_ts()}
            _write_json_file(self.admin_config_path, payload)
        try:
            os.chmod(self.admin_config_path, 0o600)
        except Exception:
            pass
        return {"ok": True, "draft": clean, "defaults": payload["defaults"], "effective_ports": ports, "restart_required": clean != self.admin_active_config}

    def reset_admin_config(self, target: str = "initial") -> dict:
        current = _read_json_file(self.admin_config_path, {})
        if target == "default":
            values = current.get("defaults", self.admin_initial_config) if isinstance(current, dict) else self.admin_initial_config
        else:
            values = self.admin_initial_config
        return self.save_admin_config(values)

    def preflight_admin_restart(self, config: dict) -> dict:
        clean, errors = _admin_coerce_config(config)
        effective_ports = dict(clean.pop("_effective_ports", {}) or {})
        if errors:
            return {"ok": False, "errors": errors, "config": clean}
        host = str(clean.get("host", "") or "").strip()
        try:
            socket.getaddrinfo(host, int(clean.get("port", 0) or 0), socket.AF_INET, socket.SOCK_STREAM)
        except Exception as exc:
            errors.append({"key": "host", "error": f"host cannot be bound by the HTTP server: {exc}"})
        config_source = str(clean.get("config", "") or "").strip()
        if config_source:
            try:
                external_config, _source = load_llm_config_from_source(
                    config_source,
                    base_dir=self.workspace,
                    timeout=5,
                )
                parse_llm_config_profiles(
                    external_config,
                    str(clean.get("ollama_base_url", DEFAULT_OLLAMA_BASE_URL) or DEFAULT_OLLAMA_BASE_URL),
                    str(clean.get("model", DEFAULT_OLLAMA_MODEL) or DEFAULT_OLLAMA_MODEL),
                )
            except Exception as exc:
                errors.append({"key": "config", "error": f"startup config cannot be loaded: {exc}"})
        enabled = {
            "agent": True,
            "skills": bool(clean.get("skills_ui_enabled")),
            "rag": bool(clean.get("rag_admin_enabled")),
            "code": bool(clean.get("code_admin_enabled")),
            "mcp": bool(clean.get("mcp_service_enabled")),
            "ide": bool(clean.get("ide_enabled")),
        }
        error_keys = {
            "agent": "port",
            "skills": "skills_port",
            "rag": "rag_admin_port",
            "code": "code_admin_port",
            "mcp": "mcp_service_port",
            "ide": "ide_port",
        }
        owned_ports = {int(getattr(self, "agent_port", 0) or 0)}
        for service, enabled_attr, port_attr in (
            ("skills", "skills_ui_enabled", "skills_port"),
            ("rag", "rag_admin_enabled", "rag_admin_port"),
            ("code", "code_admin_enabled", "code_admin_port"),
            ("mcp", "mcp_service_enabled", "mcp_service_port"),
            ("ide", "ide_enabled", "ide_port"),
        ):
            if bool(getattr(self, enabled_attr, False)):
                owned_ports.add(int(getattr(self, port_attr, 0) or 0))
        if not errors:
            for service, port_value in effective_ports.items():
                if not enabled.get(service, False):
                    continue
                port = int(port_value or 0)
                if port in owned_ports:
                    continue
                probe = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
                try:
                    probe.bind((host, port))
                except OSError as exc:
                    errors.append({
                        "key": error_keys.get(service, "port"),
                        "error": f"port {port} is unavailable for {service}: {exc}",
                    })
                finally:
                    probe.close()
        try:
            argv = _admin_config_to_argv(clean)
        except Exception as exc:
            errors.append({"key": "startup", "error": f"startup arguments cannot be compiled: {exc}"})
            argv = []
        return {
            "ok": not errors,
            "errors": errors,
            "config": clean,
            "argv": argv,
            "target": {"host": host, "port": int(clean.get("port", 0) or 0)},
        }

    def claim_admin_restart(self, config: dict, *, expected_boot_id: str = "") -> tuple[bool, str]:
        with self.restart_lock:
            current_boot = str(getattr(self.telemetry, "boot_id", "") or "")
            if not expected_boot_id or not hmac.compare_digest(str(expected_boot_id), current_boot):
                return False, "boot_conflict"
            if self.restart_pending:
                return False, "pending"
            self.restart_pending = True
            self.restart_config = dict(config)
            self.restart_fallback_config = dict(self.admin_active_config)
            self.restart_nonce = uuid.uuid4().hex
            self.restart_from_boot_id = current_boot
            try:
                self.admin_restart_error_path.unlink(missing_ok=True)
            except Exception:
                pass
            return True, self.restart_nonce

    def _session_watchdog_loop(self):
        while not self._session_watchdog_stop.is_set():
            try:
                self._session_watchdog_scan()
            except Exception:
                pass
            self._session_watchdog_stop.wait(float(SESSION_WATCHDOG_INTERVAL_SECONDS))

    def _session_watchdog_scan(self):
        now_value = now_ts()
        with self._lock:
            managers = list(self._session_mgrs.values())
        recovered_rows: list[tuple[str, str]] = []
        for mgr in managers:
            try:
                with mgr.lock:
                    sessions = list(mgr.sessions.values())
            except Exception:
                continue
            for sess in sessions:
                try:
                    if sess.recover_if_stale(now_value, SESSION_HEARTBEAT_STALE_SECONDS):
                        recovered_rows.append((str(getattr(mgr, "user_id", "") or ""), str(getattr(sess, "id", "") or "")))
                        try:
                            sess._emit(
                                "status",
                                {
                                    "summary": (
                                        str(getattr(sess, "run_recovered_reason", "") or "")
                                        or "session recovered by watchdog"
                                    )
                                },
                            )
                        except Exception:
                            pass
                except Exception:
                    continue
        if recovered_rows and self.scheduler_limits_enabled():
            for uid, sid in recovered_rows[:16]:
                try:
                    self._on_session_run_finished(uid, sid)
                except Exception:
                    continue

    def _builtin_web_ui_assets(self) -> dict[str, str]:
        cached = getattr(self, "_builtin_web_ui_assets_cache", None)
        if isinstance(cached, dict) and cached:
            return cached
        assets = {
            "index.html": INDEX_HTML,
            "style.css": APP_CSS,
            "app.js": APP_JS,
            "app.ts": APP_TS,
            "skills.html": SKILLS_INDEX_HTML,
            "skills.js": SKILLS_APP_JS,
            "skills-extra.css": SKILLS_EXTRA_CSS,
        }
        self._builtin_web_ui_assets_cache = assets
        return assets

    def _resolve_external_web_ui_file(self, root: Path, name: str) -> Path | None:
        candidates = [root / name, root / "frontend" / name]
        for fp in candidates:
            try:
                if fp.exists() and fp.is_file():
                    return fp
            except Exception:
                continue
        return None

    def validate_external_web_ui(self, ui_dir: Path) -> dict:
        root = resolve_web_ui_dir_path(str(ui_dir), self.workspace)
        out: dict = {
            "ok": False,
            "dir": str(root),
            "required_files": list(WEB_UI_REQUIRED_FILES),
            "optional_files": list(WEB_UI_OPTIONAL_FILES),
            "resolved_files": {},
            "missing_files": [],
            "errors": [],
            "checked_at": now_ts(),
        }
        if not root.exists():
            out["errors"].append("directory_not_found")
            return out
        if not root.is_dir():
            out["errors"].append("not_a_directory")
            return out
        for name in WEB_UI_REQUIRED_FILES:
            fp = self._resolve_external_web_ui_file(root, name)
            if not fp:
                out["missing_files"].append(name)
                continue
            txt = try_read_text(fp, max_bytes=4_000_000)
            if txt is None:
                out["errors"].append(f"unreadable:{name}")
                continue
            if not str(txt).strip():
                out["errors"].append(f"empty:{name}")
                continue
            out["resolved_files"][name] = str(fp)
        for name in WEB_UI_OPTIONAL_FILES:
            fp = self._resolve_external_web_ui_file(root, name)
            if fp:
                out["resolved_files"][name] = str(fp)
        for name, markers in WEB_UI_APPLICATION_FEATURE_MARKERS.items():
            fp_raw = str(out["resolved_files"].get(name, "") or "")
            txt = try_read_text(Path(fp_raw), max_bytes=4_000_000) if fp_raw else None
            if txt is None or any(marker not in txt for marker in markers):
                out["errors"].append(f"missing_application_store_contract:{name}")
        out["ok"] = not out["missing_files"] and not out["errors"]
        return out

    def _load_external_web_ui_assets(self, resolved_files: dict) -> tuple[dict[str, str], list[str]]:
        assets: dict[str, str] = {}
        errs: list[str] = []
        for name, fp_raw in resolved_files.items():
            fp = Path(str(fp_raw))
            txt = try_read_text(fp, max_bytes=4_000_000)
            if txt is None:
                errs.append(f"read_failed:{name}")
                continue
            assets[name] = txt
        return assets, errs

    def export_builtin_web_ui(self, ui_dir: Path, overwrite: bool = False) -> dict:
        root = resolve_web_ui_dir_path(str(ui_dir), self.workspace)
        root.mkdir(parents=True, exist_ok=True)
        assets = self._builtin_web_ui_assets()
        written: list[str] = []
        skipped: list[str] = []
        errors: list[str] = []
        for name, content in assets.items():
            fp = root / name
            try:
                if fp.exists() and not overwrite:
                    skipped.append(str(fp))
                    continue
                fp.parent.mkdir(parents=True, exist_ok=True)
                fp.write_text(content, encoding="utf-8")
                written.append(str(fp))
            except Exception as exc:
                errors.append(f"{name}:{exc}")
        return {
            "ok": not errors,
            "dir": str(root),
            "written": written,
            "skipped": skipped,
            "errors": errors,
        }

    def web_ui_status(self) -> dict:
        mode = "external" if self.web_ui_external_enabled else "builtin"
        return {
            "mode": mode,
            "external_requested": bool(self.web_ui_external_requested),
            "external_enabled": bool(self.web_ui_external_enabled),
            "config_path": str(self.web_ui_config_path or ""),
            "dir": str(self.web_ui_dir),
            "show_upload_list": bool(getattr(self, "show_upload_list", False)),
            "ui_style": normalize_ui_style(getattr(self, "ui_style", DEFAULT_UI_STYLE)),
            "js_lib_download_enabled": bool(getattr(self, "js_lib_download_enabled", True)),
            "shell_command_timeout_seconds": int(getattr(self, "shell_command_timeout_seconds", DEFAULT_SHELL_COMMAND_TIMEOUT_SECONDS) or DEFAULT_SHELL_COMMAND_TIMEOUT_SECONDS),
            "daily_session_limit_per_ip": int(getattr(self, "daily_session_limit_per_ip", 0) or 0),
            "daily_session_reset_hour": int(getattr(self, "daily_session_reset_hour", 8) or 8),
            "validation": dict(self.web_ui_validation or {}),
        }

    def configure_web_ui(
        self,
        *,
        config_path: str = "",
        ui_dir: Path | str | None = None,
        enable_external: bool = False,
        export_builtin: bool = False,
        export_overwrite: bool = False,
        show_upload_list: bool | None = None,
    ) -> dict:
        self.web_ui_config_path = str(config_path or self.web_ui_config_path or "")
        self.web_ui_dir = resolve_web_ui_dir_path(str(ui_dir or DEFAULT_WEB_UI_DIR), self.workspace)
        if show_upload_list is not None:
            self.show_upload_list = bool(show_upload_list)
        export_result: dict = {}
        if export_builtin:
            export_result = self.export_builtin_web_ui(self.web_ui_dir, overwrite=bool(export_overwrite))
        self.web_ui_external_requested = bool(enable_external)
        self.web_ui_external_enabled = False
        self.web_ui_assets_override = {}
        self.web_ui_validation = self.validate_external_web_ui(self.web_ui_dir)
        if self.web_ui_external_requested and bool(self.web_ui_validation.get("ok", False)):
            assets, errs = self._load_external_web_ui_assets(
                self.web_ui_validation.get("resolved_files", {}) if isinstance(self.web_ui_validation, dict) else {}
            )
            if not errs:
                self.web_ui_assets_override = assets
                self.web_ui_external_enabled = True
            else:
                self.web_ui_validation = dict(self.web_ui_validation)
                self.web_ui_validation["ok"] = False
                self.web_ui_validation["errors"] = list(self.web_ui_validation.get("errors", [])) + errs
        elif self.web_ui_external_requested:
            self.web_ui_validation = dict(self.web_ui_validation)
            self.web_ui_validation.setdefault("errors", [])
            if "validation_failed" not in self.web_ui_validation["errors"]:
                self.web_ui_validation["errors"].append("validation_failed")
        else:
            self.web_ui_validation = dict(self.web_ui_validation)
            self.web_ui_validation["ok"] = False
            self.web_ui_validation["reason"] = "external_web_ui_disabled"
        out = self.web_ui_status()
        out["export"] = export_result
        return out

    def refresh_web_ui_validation(self, reload_external: bool = False) -> dict:
        validation = self.validate_external_web_ui(self.web_ui_dir)
        self.web_ui_validation = validation
        if reload_external and self.web_ui_external_requested:
            self.web_ui_external_enabled = False
            self.web_ui_assets_override = {}
            if bool(validation.get("ok", False)):
                assets, errs = self._load_external_web_ui_assets(validation.get("resolved_files", {}))
                if not errs:
                    self.web_ui_assets_override = assets
                    self.web_ui_external_enabled = True
                else:
                    self.web_ui_validation = dict(validation)
                    self.web_ui_validation["ok"] = False
                    self.web_ui_validation["errors"] = list(self.web_ui_validation.get("errors", [])) + errs
        return self.web_ui_status()

